	lda     __y
	asl     a
	bcc     L1C26
	inx
L1C26:	sta     ptr1
	stx     ptr1+1
	lda     __x
	cmp     #$08
	lda     #$00
	rol     a
	ora     ptr1
	clc
	adc     #<(_screen_clear_list)
	tay
	lda     ptr1+1
	adc     #>(_screen_clear_list)
	tax
	tya
	jsr     pushax
	sta     ptr1
	stx     ptr1+1
	ldy     #$00
	lda     (ptr1),y
	sta     sreg
	lda     __x
	and     #$07
	sta     ptr1
	tya
	clc
	adc     #>(_bits)
	sta     ptr1+1
	ldy     #<(_bits)
	lda     (ptr1),y
	ora     sreg
	ldy     #$00
	jmp     staspidx

.endproc

